#!/usr/bin/env bash
# table of the runs of tdet1.py from its log (family, vectors, slicing size and B, terms of N~, time)
awk '/^MT sym \[|^MU sym \[/ && !/PD on|FAILED/ {fam=$0} /: [0-9]+ vectors, largest entry/ {match($0, /form: [0-9]+ vectors/); nv=substr($0, RSTART+6, RLENGTH-14)} /slices in/ {match($0, /slices in [a-z0-9]+: 0\.\.[0-9]+/); sl=substr($0, RSTART+10, RLENGTH-10)} /N~: [0-9]+ terms/ {match($0, /N~: [0-9]+ terms/); nt=substr($0, RSTART+4, RLENGTH-10); match($0, /degrees \([^)]*\)/); dg=substr($0, RSTART+8, RLENGTH-8); match($0, /[0-9]+ negative/); ng=substr($0, RSTART, RLENGTH)} /PD on complement|FAILED/ && /\(/ {match($0, /\(([0-9.]+)s\)$/); tm=substr($0, RSTART+1, RLENGTH-3); st=($0 ~ /PD on/) ? "PD" : "FAILED"; f=fam; gsub(/MT sym |MU sym /, "", f); print "| " f " | " nv " | " sl " | " nt " | " dg " | " ng " | " tm " | " st " |"}' "$1"
